import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,M as n,N as r,O as i,P as a,S as o,b as s,h as c,i as l,k as u,l as d,n as f,o as p,r as m,t as h,v as g,x as _}from"./shared-DP9JVsk0.js";import{t as v}from"./CodeEditor-BZlrvoTL.js";var y=e();function b({module:e}){return(0,y.jsxs)(r,{children:[(0,y.jsx)(n,{chip:e??`Блок 4 · Собираем свой Planner`,title:`16. Запускаем каркас Planner`,intro:`Перейдём от подготовленных функций к программе, которая принимает команды в одном запуске и возвращает нас к меню.`}),(0,y.jsxs)(a,{number:`00`,title:`От демо к пользовательскому циклу`,children:[(0,y.jsx)(i,{children:`В демо функции запускались по заранее записанным вызовам. Теперь команда пользователя будет выбирать действие, а программа возвращаться к меню.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Откроем свой main.py, найдём normalize_title, create_task, format_task и calculate_study_minutes, затем запустим прежнее демо.`},{title:`Новый вопрос`,description:`Как программа несколько раз принимает команду, сохраняя общий список в течение одного запуска, если добавление задач пока не подключено?`},{title:`Результат`,description:`Вместо демо работает минимальный Planner: команды list и exit, отказ на неизвестный ввод и ясные временные ответы для будущих действий.`}]}),(0,y.jsx)(`p`,{children:`Сохраним прежнее поведение как ориентир. В новом каркасе заменим только демо, а четыре функции оставим на месте.`}),(0,y.jsx)(`p`,{children:`Новый интерфейс свяжет показ меню, ввод команды и ответ в одном запуске. Пока задачи нельзя добавлять или менять: мы подготовим цикл и оставим будущим командам честные временные ответы.`})]}),(0,y.jsxs)(a,{number:`01`,title:`Кто управляет запуском`,children:[(0,y.jsx)(i,{children:`Отдельная функция запуска связывает подготовленные части приложения, но не забирает на себя каждую работу.`}),(0,y.jsxs)(`p`,{children:[`В Planner следующую операцию выбирает человек. Функция `,(0,y.jsx)(`code`,{children:`run()`}),` координирует этот процесс: вызывает меню, получает команду и передаёт управление нужной функции. `,(0,y.jsx)(`code`,{children:`run`}),` — обычное имя; важна его роль в программе.`]}),(0,y.jsxs)(`p`,{children:[(0,y.jsx)(`code`,{children:`show_menu()`}),` только печатает варианты. Она не читает ввод и не выбирает ветку: это делает`,(0,y.jsx)(`code`,{children:`run()`}),`. Операции позже выполнят отдельные функции. Поэтому строка `,(0,y.jsx)(`code`,{children:`add`}),` в меню ещё не означает, что добавление уже работает.`]}),(0,y.jsxs)(`p`,{children:[`Вызов `,(0,y.jsx)(`code`,{children:`show_menu()`}),` на время передаёт ей управление. Когда печать заканчивается, выполнение возвращается в `,(0,y.jsx)(`code`,{children:`run()`}),` к следующей строке, где можно получить ввод. Само меню не возвращает выбранный пункт: текст на экране и команда, которую читает `,(0,y.jsx)(`code`,{children:`run()`}),`, — разные части диалога. Если смешать их, изменение подписи может случайно затронуть выбор действия.`]}),(0,y.jsxs)(`p`,{children:[`Если поместить чтение команды в `,(0,y.jsx)(`code`,{children:`show_menu()`}),`, её вызов уже будет не просто показом вариантов. Если поместить туда же вызов `,(0,y.jsx)(`code`,{children:`show_tasks()`}),`, список начнёт печататься при каждом показе меню, даже когда выбрано другое действие. Разделение ролей не даёт такому побочному действию появиться.`]}),(0,y.jsxs)(`p`,{children:[`Представим стойку справок: табличка с услугами похожа на `,(0,y.jsx)(`code`,{children:`show_menu()`}),`, а сотрудник, который направляет запрос, — на `,(0,y.jsx)(`code`,{children:`run()`}),`. В программе маршрут задают только точные команды, а не смысл свободного вопроса. Сотрудник не выполняет каждую услугу сам: он направляет человека к нужной работе.`]}),(0,y.jsx)(`p`,{children:`Меню само по себе не доказывает, что каждая его строка уже работает. Например, надпись «найти задачу» может появиться раньше, чем будет написан поиск. Мы будем различать три вещи: подпись, распознаваемую команду и выполненную операцию. В текущем результате только несколько команд имеют настоящую ветвь. Для остальных потребуется честный ответ, а не сообщение о несуществующем успехе.`}),(0,y.jsx)(s,{question:`Что происходит, если show_menu() напечатала строку add?`,options:[`Задача уже добавлена в tasks`,`На экране есть подпись, но действие ещё может быть не подключено`,`run() завершился`],correctIndex:1,explanation:`Мы разделили отображение и обработку. Чтобы действие стало реальным, программа должна получить команду и пройти по её рабочей ветви.`})]}),(0,y.jsxs)(a,{number:`02`,title:`Список на время одного запуска`,children:[(0,y.jsx)(i,{children:`Сначала определим, кто создаёт общий список и как долго он остаётся доступным.`}),(0,y.jsxs)(`p`,{children:[`Будущие команды будут читать и менять общий `,(0,y.jsx)(`code`,{children:`tasks`}),`. Создадим его один раз в начале`,(0,y.jsx)(`code`,{children:`run()`}),`, до цикла: тогда все ветви этого запуска увидят один список. Пока он пуст, а его создание само по себе не добавляет задачи.`]}),(0,y.jsxs)(`p`,{children:[`Когда `,(0,y.jsx)(`code`,{children:`run()`}),` вызывает `,(0,y.jsx)(`code`,{children:`show_tasks(tasks)`}),`, параметр `,(0,y.jsx)(`code`,{children:`tasks`}),` внутри функции ссылается на тот же список. Функция показа может прочитать его, а будущая операция добавления сможет изменить. Для этого список передают аргументом, а не создают заново внутри помощника и не прячут в глобальной переменной. Сейчас `,(0,y.jsx)(`code`,{children:`show_tasks`}),` только печатает и не меняет содержимое.`]}),(0,y.jsxs)(`p`,{children:[`Явный аргумент показывает, от каких данных зависит функция. Мы можем передать ей список из запуска или отдельный пример для проверки. Когда будущая команда добавит запись в общий объект, `,(0,y.jsx)(`code`,{children:`run()`}),`увидит это изменение на следующем проходе без отдельного возвращаемого списка.`]}),(0,y.jsxs)(`p`,{children:[`Если создавать `,(0,y.jsx)(`code`,{children:`tasks`}),` внутри цикла, каждый проход будет начинаться с нового пустого списка, и добавленные записи потеряются. Если помощник создаст собственный пустой список, он тоже будет отдельным объектом и не покажет состояние `,(0,y.jsx)(`code`,{children:`run()`}),`. Локальная переменная запуска задаёт владельца, а аргументы дают функциям доступ к нужному состоянию.`]}),(0,y.jsxs)(`p`,{children:[`Область жизни ограничена запуском `,(0,y.jsx)(`code`,{children:`run()`}),`. При штатном `,(0,y.jsx)(`code`,{children:`exit`}),` функция заканчивается; следующий запуск создаёт новый список. Чтобы задачи переживали закрытие программы, потребовалось бы сохранение вне памяти процесса, но его в этом каркасе ещё нет.`]}),(0,y.jsx)(`p`,{children:`Представим одну корзину на время смены: каждое обращение видит её содержимое, а при новой смене появляется пустая корзина. Аналогия помогает увидеть срок жизни состояния; список Python хранится в памяти процесса и исчезает после его завершения.`}),(0,y.jsx)(v,{caption:`Фрагмент расположения состояния, не полное определение run()`,code:`def run():
    tasks = []
    while True:
        # здесь начинается очередной проход меню`}),(0,y.jsxs)(`p`,{children:[`Это фрагмент расположения, а не готовая функция: `,(0,y.jsx)(`code`,{children:`tasks`}),` находится внутри `,(0,y.jsx)(`code`,{children:`run()`}),`, но вне тела `,(0,y.jsx)(`code`,{children:`while`}),`. Так список переживает отдельные проходы.`]}),(0,y.jsx)(h,{caption:`Один владелец состояния и повторные команды`,className:`lesson36-loop-diagram`,children:(0,y.jsxs)(p,{label:`Запуск, список и путь одной команды`,orientation:`vertical`,children:[(0,y.jsx)(d,{title:`run() начинает запуск`,shape:`terminator`,children:(0,y.jsx)(`p`,{children:`Здесь создаётся один пустой tasks`})}),(0,y.jsx)(f,{label:`список создан до цикла`}),(0,y.jsx)(d,{title:`Начинается проход while`,className:`lesson36-loop-node`,children:(0,y.jsx)(`p`,{children:`Показываем меню и получаем одну команду`})}),(0,y.jsx)(f,{label:`выбираем маршрут команды`}),(0,y.jsxs)(l,{label:`Доступная команда, будущая команда, неизвестный ввод или выход`,children:[(0,y.jsx)(m,{label:`list`,children:(0,y.jsxs)(p,{label:`Читаем общий список`,orientation:`vertical`,children:[(0,y.jsx)(d,{title:`show_tasks(tasks)`,children:(0,y.jsx)(`p`,{children:`Пока показывает пустоту или честную временную заметку`})}),(0,y.jsx)(f,{label:`следующий проход цикла`,direction:`backward`})]})}),(0,y.jsx)(m,{label:`Будущее действие или неизвестный ввод`,children:(0,y.jsxs)(p,{label:`Отвечаем и возвращаемся к меню`,orientation:`vertical`,children:[(0,y.jsx)(d,{title:`Печатаем точный статус`}),(0,y.jsx)(f,{label:`continue возвращает к новому проходу`,direction:`backward`})]})}),(0,y.jsx)(m,{label:`exit`,children:(0,y.jsx)(p,{label:`Завершаем текущий запуск`,orientation:`vertical`,children:(0,y.jsx)(d,{title:`break выходит из while`,shape:`terminator`})})})]})]})}),(0,y.jsxs)(`p`,{children:[`Читаем схему сверху вниз. Список создаётся перед входом в повторение. Команда `,(0,y.jsx)(`code`,{children:`list`}),` получает ссылку на то же состояние. Будущая или неизвестная команда заканчивает текущий проход, и управление возвращается к проверке цикла. Только ветка `,(0,y.jsx)(`code`,{children:`exit`}),` завершает повторение. Схема описывает план каркаса, она не утверждает, что все операции над задачами уже реализованы.`]})]}),(0,y.jsxs)(a,{number:`03`,title:`Как run передаёт управление`,children:[(0,y.jsxs)(i,{children:[`Цикл уже знаком; проследим, как `,(0,y.jsx)(`code`,{children:`run()`}),` вызывает функции, передаёт им общий список и получает управление обратно.`]}),(0,y.jsxs)(`p`,{children:[`В каждом проходе `,(0,y.jsx)(`code`,{children:`run()`}),` вызывает `,(0,y.jsx)(`code`,{children:`show_menu()`}),`, читает одну команду и выбирает ветвь. При `,(0,y.jsx)(`code`,{children:`list`}),` он передаёт тот же `,(0,y.jsx)(`code`,{children:`tasks`}),` в `,(0,y.jsx)(`code`,{children:`show_tasks(tasks)`}),`. Когда функция заканчивает показ, управление возвращается в `,(0,y.jsx)(`code`,{children:`run()`}),`, затем начинается следующий проход с тем же списком.`]}),(0,y.jsxs)(`p`,{children:[`Вызов не перезапускает файл и не создаёт новую функцию запуска. Python выполняет тело вызванной функции, доходит до его конца и продолжает после строки вызова. Поэтому `,(0,y.jsx)(`code`,{children:`show_tasks`}),` не решает, какую команду принять следующей: это решение остаётся у `,(0,y.jsx)(`code`,{children:`run()`}),`. Такой порядок сохраняет один центр управления, даже если список действий вырастет.`]}),(0,y.jsxs)(`p`,{children:[`Ветвь `,(0,y.jsx)(`code`,{children:`exit`}),` заканчивает цикл знакомой командой `,(0,y.jsx)(`code`,{children:`break`}),`. Для неизвестной или пока не подключённой команды мы печатаем сообщение и переходим к следующему проходу. `,(0,y.jsx)(`code`,{children:`continue`}),` нужен, если после этой ветви в текущем проходе остались строки, которые выполнять не следует.`]}),(0,y.jsxs)(`p`,{children:[`Проследим три маршрута. После `,(0,y.jsx)(`code`,{children:`list`}),` `,(0,y.jsx)(`code`,{children:`run()`}),` получает управление обратно и снова показывает меню; состояние не сбрасывается. Для будущей команды та же функция сообщает, что действие ещё не подключено. Для неизвестного слова она объясняет отказ. Только `,(0,y.jsx)(`code`,{children:`exit`}),` завершает повторение. Команды отличаются результатом ветви, а общий порядок показа и чтения остаётся тем же.`]}),(0,y.jsxs)(`p`,{children:[`Когда в следующих шагах появятся обработчики, маршрут сохранится: `,(0,y.jsx)(`code`,{children:`run()`}),` распознает команду, вызовет нужную функцию и передаст ей необходимые данные. Обработчик выполнит одно действие и вернёт управление координатору. Сейчас эту будущую работу заменяет временный ответ, поэтому заглушка не меняет`,(0,y.jsx)(`code`,{children:`tasks`}),` и не создаёт впечатления, что задача уже добавлена.`]}),(0,y.jsx)(t,{rows:[[`list`,(0,y.jsxs)(y.Fragment,{children:[(0,y.jsx)(`code`,{children:`run()`}),` передаёт общий список в `,(0,y.jsx)(`code`,{children:`show_tasks(tasks)`}),`.`]})],[`неизвестная команда`,(0,y.jsx)(y.Fragment,{children:`Печатаем отказ и возвращаем управление к следующему проходу.`})],[`exit`,(0,y.jsxs)(y.Fragment,{children:[(0,y.jsx)(`code`,{children:`break`}),` завершает цикл внутри `,(0,y.jsx)(`code`,{children:`run()`}),`.`]})]]}),(0,y.jsx)(s,{question:`Что происходит после того, как show_tasks(tasks) закончила показ?`,options:[`run() продолжает работу, а следующий проход использует тот же tasks`,`Создаётся новый tasks для следующей команды`,`show_menu() выбирает и выполняет следующую команду`],correctIndex:0,explanation:`show_tasks отвечает только за показ. run управляет следующим шагом и сохраняет владение одним списком в течение запуска.`})]}),(0,y.jsxs)(a,{number:`04`,title:`Нормализуем строку до сравнения`,children:[(0,y.jsx)(i,{children:`Перед выбором ветви сведём ввод к предсказуемому ключу команды.`}),(0,y.jsxs)(`p`,{children:[`Пользователь может добавить пробелы по краям или написать команду заглавными буквами. Привычная цепочка`,(0,y.jsx)(`code`,{children:`strip().lower()`}),` превращает `,(0,y.jsx)(`code`,{children:`" LIST "`}),` в `,(0,y.jsx)(`code`,{children:`"list"`}),`; сравниваем именно подготовленное значение `,(0,y.jsx)(`code`,{children:`command`}),`.`]}),(0,y.jsxs)(`p`,{children:[`Методы не удаляют внутренние пробелы, поэтому `,(0,y.jsx)(`code`,{children:`"show all"`}),` так и останется неизвестным вводом. Правила команд задаются отдельно от `,(0,y.jsx)(`code`,{children:`normalize_title()`}),`: готовую функцию для названий задач мы не меняем.`]}),(0,y.jsx)(c,{code:`command = raw_command.strip().lower()
if command == "list":
    print("Показываем список")
elif command == "exit":
    print("Завершаем цикл")
else:
    print("Неизвестная команда")`,scenarios:[{label:`" LIST "`,activeLine:1,output:`Показываем список`},{label:`" EXIT "`,activeLine:3,output:`Завершаем цикл`},{label:`"show all"`,activeLine:5,output:`Команда не распознана`}]}),(0,y.jsxs)(`p`,{children:[`После нормализации `,(0,y.jsx)(`code`,{children:`list`}),` и `,(0,y.jsx)(`code`,{children:`exit`}),` выбирают свои ветви, а несовпавшее значение доходит до общего отказа. Внутренние пробелы и незнакомые слова автоматически не исправляются.`]}),(0,y.jsx)(`p`,{children:`Нормализация происходит до маршрутизации, поэтому правило одинаково для доступных и будущих команд.`})]}),(0,y.jsxs)(a,{number:`05`,title:`Действующие и временные ветви`,children:[(0,y.jsx)(i,{children:`На этом шаге рабочими становятся только list и exit. Остальные названия помогают увидеть маршрут продукта, но отвечают честным временным сообщением.`}),(0,y.jsxs)(`p`,{children:[`У Planner есть будущий набор действий: добавить задачу, показать список, найти запись, отметить её выполненной, отобрать совпадения, посчитать сводку и выйти. Сейчас мы подключим только `,(0,y.jsx)(`code`,{children:`list`}),` и`,(0,y.jsx)(`code`,{children:`exit`}),`. Остальные команды можно оставить в меню с пометкой, что они ещё не подключены. Такой список помогает видеть целое приложение, но это не приглашение вызывать отсутствующие функции.`]}),(0,y.jsxs)(`p`,{children:[`Ветвь `,(0,y.jsx)(`code`,{children:`list`}),` вызывает простую `,(0,y.jsx)(`code`,{children:`show_tasks(tasks)`}),`. Если список пуст, она печатает сообщение о пустоте. Если передать непустой список напрямую, текущая версия должна сообщить, что полный показ появится позже. Мы различаем пустые данные и ещё не готовое отображение. Если для обоих случаев напечатать «задач нет», человек получит ложную информацию о состоянии программы.`]}),(0,y.jsxs)(`p`,{children:[`Чтобы различить состояния, посмотрим на количество элементов: `,(0,y.jsx)(`code`,{children:`len(tasks)`}),` возвращает число записей. Если это число равно нулю, список пуст. Если оно больше нуля, в списке есть данные, даже если полный вывод ещё не написан. Здесь мы используем длину только как проверку состояния, не превращаем её в id задачи и не связываем количество с порядком будущих записей.`]}),(0,y.jsxs)(`p`,{children:[`Меню похоже на карту здания: оно показывает названия кабинетов, но не подтверждает, что каждый кабинет уже открыт. Сообщение «команда пока не подключена» обозначает реальную границу текущего шага. Оно отличается от общего отказа: имя будущего действия известно курсу, а неизвестное имя не относится к согласованному набору. И в том и в другом случае мы не меняем `,(0,y.jsx)(`code`,{children:`tasks`}),` и возвращаем человека к следующему показу меню.`]}),(0,y.jsxs)(`p`,{children:[`Ветвь выхода должна сравнить подготовленную команду с `,(0,y.jsx)(`code`,{children:`exit`}),` и выполнить `,(0,y.jsx)(`code`,{children:`break`}),`. Ветвь списка передаёт тот же объект `,(0,y.jsx)(`code`,{children:`tasks`}),` функции отображения. Неизвестная команда получает отказ и переходит к следующему проходу. Будущие ветви показывают временный статус и тоже ничего не добавляют, не ищут и не отмечают. На следующих занятиях их постепенно заменят реальные обработчики.`]}),(0,y.jsxs)(`p`,{children:[`Такая маршрутизация разделяет знание о команде и саму операцию. `,(0,y.jsx)(`code`,{children:`run()`}),` знает, что слово`,(0,y.jsx)(`code`,{children:`list`}),` направляет к показу, а слово `,(0,y.jsx)(`code`,{children:`exit`}),` завершает цикл. Он не должен знать, как форматировать отдельную задачу или вычислять статистику. Эту ответственность получат специализированные функции, когда соответствующие действия появятся.`]}),(0,y.jsx)(t,{rows:[[`list`,(0,y.jsxs)(y.Fragment,{children:[`Вызывает минимальную `,(0,y.jsx)(`code`,{children:`show_tasks(tasks)`}),`.`]})],[`exit`,(0,y.jsxs)(y.Fragment,{children:[`Выполняет `,(0,y.jsx)(`code`,{children:`break`}),` и завершает цикл.`]})],[`add`,(0,y.jsx)(y.Fragment,{children:`Показывает, что добавление будет подключено позже.`})],[`find`,(0,y.jsx)(y.Fragment,{children:`Показывает, что поиск одной задачи будет подключён позже.`})],[`done`,(0,y.jsx)(y.Fragment,{children:`Показывает, что изменение состояния будет подключено позже.`})],[`search`,(0,y.jsx)(y.Fragment,{children:`Показывает, что поиск совпадений будет подключён позже.`})],[`stats`,(0,y.jsx)(y.Fragment,{children:`Показывает, что сводка будет подключена позже.`})]]}),(0,y.jsx)(`p`,{children:`Запомним три разных результата. Поддержанная команда выполняет доступное действие. Известная будущая команда получает временный статус. Любая другая строка получает сообщение об ошибке. Успех нельзя печатать только потому, что программа распознала слово: за каждой рабочей ветвью должно стоять реальное действие.`}),(0,y.jsx)(o,{statement:(0,y.jsxs)(y.Fragment,{children:[`Если в меню напечатана команда `,(0,y.jsx)(`code`,{children:`stats`}),`, build_statistics уже должна быть вызвана.`]}),isTrue:!1,explanation:`Мы можем показать будущую команду раньше её реализации. На этом шаге ветвь stats сообщает о временном статусе и не вызывает отсутствующую функцию.`})]}),(0,y.jsxs)(a,{number:`05.1`,title:`Полный пример: каталог с двумя командами`,children:[(0,y.jsx)(i,{children:`Перед сборкой Planner проследим целую запускаемую программу. В каталоге уже есть две страницы; команда count показывает их число, exit завершает работу.`}),(0,y.jsx)(`p`,{children:`Здесь два вида состояния: список страниц и число просмотров. Оба создаются до цикла. Меню только печатает подсказку, помощник только читает переданный список, а run_catalog выбирает действия и продолжает работу после вызова. Счётчик нужен этому примеру; добавлять его в Planner не требуется.`}),(0,y.jsx)(g,{code:`def show_options():
    print("Команды: count, exit")

def show_count(pages):
    print("Страниц:", len(pages))

def run_catalog():
    pages = ["Карта", "Памятка"]
    views = 0
    while True:
        show_options()
        command = input("Команда: ").strip().lower()
        if command == "exit":
            break
        if command == "count":
            show_count(pages)
            views += 1
            print("Просмотров:", views)
        else:
            print("Неизвестная команда")

run_catalog()
print("Каталог закрыт")`,steps:[{line:21,note:`Начинается один вызов каталога. Для примера вводим count, неизвестное слово, count и exit.`,vars:{}},{line:7,note:`Один список создаётся до цикла. Во всех командах этого вызова будет использоваться он.`,vars:{pages:`[Карта, Памятка]`}},{line:8,note:`Счётчик просмотров также создаётся один раз.`,vars:{views:`0`}},{line:10,note:`Функция печатает меню и возвращает управление в run_catalog.`,vars:{views:`0`}},{line:11,note:`Первый ответ count получен как строка. Выбираем соответствующую ветвь.`,vars:{command:`count`,views:`0`}},{line:15,note:`Передаём существующий список в помощник. Новый список не создаётся.`,vars:{pages:`[Карта, Памятка]`}},{line:4,note:`Помощник показывает «Страниц: 2» и заканчивается. Управление вернётся после вызова.`,vars:{pages:`тот же список`}},{line:16,note:`После возврата продолжаем текущий проход. Счётчик становится равен 1.`,vars:{views:`1`}},{line:17,note:`Печатаем «Просмотров: 1», затем начинается очередной проход.`,vars:{views:`1`}},{line:11,note:`Второй ввод — неизвестное слово. Состояние по-прежнему принадлежит этому вызову.`,vars:{command:`слово`,views:`1`}},{line:19,note:`Общий отказ заканчивает этот проход. Список и счётчик не изменились.`,vars:{views:`1`}},{line:11,note:`Третий ввод count снова направляет к помощнику с тем же списком.`,vars:{command:`count`,views:`1`}},{line:15,note:`Помощник ещё раз показывает две страницы и возвращает управление.`,vars:{views:`1`}},{line:16,note:`Следующая строка увеличивает прежний счётчик до 2. Создания views = 0 в цикле нет.`,vars:{views:`2`}},{line:17,note:`Печатаем «Просмотров: 2». Повторный показ меню не перезапустил функцию.`,vars:{views:`2`}},{line:11,note:`Четвёртый ввод exit выбирает завершение цикла.`,vars:{command:`exit`,views:`2`}},{line:13,note:`Выходим из while. Дальше в теле функции строк нет, вызов заканчивается.`,vars:{}},{line:22,note:`Внешний script продолжает работу после вызова и печатает «Каталог закрыт».`,vars:{}}]}),(0,y.jsx)(`p`,{children:`Проверим четыре перехода: count вызывает помощник и возвращается к следующей строке; неизвестное слово получает отказ; второй count видит тот же список и прежний счётчик; exit заканчивает цикл и возвращает управление внешнему коду. Новый вызов run_catalog создал бы свои начальные данные.`}),(0,y.jsx)(`p`,{children:`Теперь сопоставим роли с Planner: владелец состояния — run, показ вариантов — show_menu, чтение списка — show_tasks. Сначала соберём минимальный запускаемый шаг, затем добавим повтор. Это соединение уже знакомых конструкций.`})]}),(0,y.jsxs)(a,{number:`06`,title:`Заменяем демо и проверяем результат`,children:[(0,y.jsx)(i,{children:`В проекте останутся четыре готовых компонента, а новый интерфейс займёт место короткого демо.`}),(0,y.jsxs)(`p`,{children:[`Сохраняем четыре готовые функции B3 и заменяем только демо. После них размещаем`,(0,y.jsx)(`code`,{children:`show_menu()`}),`, `,(0,y.jsx)(`code`,{children:`show_tasks(tasks)`}),` и `,(0,y.jsx)(`code`,{children:`run()`}),`; в конце оставляем один вызов`,(0,y.jsx)(`code`,{children:`run()`}),`.`]}),(0,y.jsxs)(`p`,{children:[`Внутри `,(0,y.jsx)(`code`,{children:`run()`}),` создаём один `,(0,y.jsx)(`code`,{children:`tasks`}),` до цикла. Команда `,(0,y.jsx)(`code`,{children:`list`}),` проверит пустое состояние, а прямой вызов `,(0,y.jsx)(`code`,{children:`show_tasks`}),` на непустом списке покажет временное ограничение.`]}),(0,y.jsxs)(`p`,{children:[`С ключом `,(0,y.jsx)(`code`,{children:`-i`}),` после завершения файла остаётся приглашение `,(0,y.jsx)(`code`,{children:`>>>`}),`. Пока меню работает, ввод относится к приложению; после `,(0,y.jsx)(`code`,{children:`exit`}),` можно вызвать `,(0,y.jsx)(`code`,{children:`show_tasks`}),`отдельно и проверить пустой и непустой список. Сверим и прежние результаты четырёх функций.`]}),(0,y.jsxs)(`p`,{children:[`В одном запуске проверим пустой `,(0,y.jsx)(`code`,{children:`list`}),`, неизвестную строку, вариант с пробелами и заглавными буквами, будущую команду и `,(0,y.jsx)(`code`,{children:`exit`}),`. После отказа меню появляется снова; нормализованный ввод выбирает нужную ветвь, а временная команда не меняет данные. Надпись в меню сама по себе не означает, что действие уже реализовано.`]}),(0,y.jsxs)(`p`,{children:[`После проверки просмотрим `,(0,y.jsx)(`code`,{children:`status`}),` и `,(0,y.jsx)(`code`,{children:`diff`}),`, затем сохраним изменение способом курса. Git хранит версию программы, но не текущий список `,(0,y.jsx)(`code`,{children:`tasks`}),`.`]}),(0,y.jsx)(_,{question:`Перед практикой вспомним роли функций: кто создаёт tasks, кто печатает меню и кто передаёт список для показа?`,hint:`Свяжем владельца состояния с вызовами функций.`,answer:(0,y.jsxs)(`ul`,{children:[(0,y.jsx)(`li`,{children:`Один tasks создаётся в run() перед циклом.`}),(0,y.jsx)(`li`,{children:`show_menu() только печатает варианты.`}),(0,y.jsx)(`li`,{children:`run() передаёт тот же список функции show_tasks(tasks).`})]})})]}),(0,y.jsxs)(a,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(i,{children:`Практика продолжает свой StudyHub и меняет демо в существующем main.py.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Сверим исходный файл`,description:`Найдём четыре готовые функции в main.py и запустим прежнее демо.`},{title:`Соберём каркас по этапам`,description:`Сначала подключим меню и выход, затем повторяемый list с одним tasks, затем нормализацию и честные временные ветви.`},{title:`Проверим и передадим`,description:`Пройдём команды и прежние функции, посмотрим diff и сохраним изменение.`}]}),(0,y.jsx)(`p`,{children:`Сначала зафиксируем, что делает прежнее демо. Затем по шагам заменим его меню и циклом, сохраняя определения четырёх функций и проверяя результат каждого изменения.`}),(0,y.jsxs)(`p`,{children:[`В результате практики приложение показывает меню, принимает несколько команд в одном запуске, хранит один локальный список до выхода, корректно выполняет `,(0,y.jsx)(`code`,{children:`list`}),` и `,(0,y.jsx)(`code`,{children:`exit`}),`, сообщает о неизвестном вводе и не выдаёт будущие операции за готовые.`]})]})]})}export{b as Lesson16};